// Hand-authored shared helpers for the scientific-consensus engines. Not
// generated; safe across regeneration (no "Generated by" header).
package cli

import (
	"fmt"
	"regexp"
	"sort"
	"strings"
)

// versionSuffixRE matches the Cochrane-style edition suffix on a DOI: the
// ".pub2" / ".pub3" / ".pub4" that Cochrane appends when it republishes a
// review. Anchored to the end so a DOI that merely contains "pub" somewhere in
// its body is untouched.
var versionSuffixRE = regexp.MustCompile(`\.pub\d+$`)

// doiFamily reduces a DOI to the identity shared by every edition of the same
// work. "10.1002/14651858.cd000980.pub4" and "10.1002/14651858.cd000980" both
// reduce to "10.1002/14651858.cd000980" — one review, not two.
//
// Returns "" for a work with no DOI, which the caller MUST treat as "not
// deduplicable" rather than as a family of its own: collapsing every DOI-less
// work into a single bucket would silently drop unrelated studies.
func doiFamily(doi string) string {
	d := strings.ToLower(strings.TrimSpace(doi))
	if d == "" {
		return ""
	}
	// OpenAlex hands DOIs back as full URLs about half the time.
	d = strings.TrimPrefix(d, "https://doi.org/")
	d = strings.TrimPrefix(d, "http://doi.org/")
	d = strings.TrimPrefix(d, "doi:")
	return versionSuffixRE.ReplaceAllString(d, "")
}

// dedupeReport is the accounting for one dedupe pass, shaped like
// relevanceReport so gateNotes can render it without special-casing.
type dedupeReport struct {
	// Excluded is how many works were dropped as superseded editions.
	Excluded int
	// Families lists one line per collapsed family, newest-kept first, so the
	// note names WHICH works were merged instead of only how many. Without this
	// a reader cannot audit the count against the study list beside it.
	Families []string
}

// dedupeVersions collapses multi-edition works to their newest edition.
//
// WHY THIS EXISTS, measured on the vitamin C corpus (2026-08-03): a live
// keyless run fetched 10 works, 9 survived the gates, and 4 of those 9 were the
// SAME Cochrane review — CD000980 as .pub4 (2013), .pub3 (2007), .pub2 (2004)
// and the 1998 original. One review cast 44% of the votes. Consensus() also
// weights by citations, so the family carried its authority in four times over
// as well. The corpus reported 9 studies; it held 6.
//
// RULE: newest edition wins, the rest are dropped, citations are NOT summed.
// Summing would put a citation count next to a DOI that did not earn it, and
// this output is meant to be auditable line by line. The kept edition is the
// one Cochrane itself considers current; the superseded ones are, in Cochrane's
// own terms, replaced rather than independent.
//
// WHAT THIS DOES NOT FIX: on the vitamin C corpus every surviving work is
// classified supporting, so the verdict stays evidence-supports and the score
// stays 1.00. This repairs the corpus's honesty (study_count), not the stance
// classifier above it. Measured, not assumed — do not expect a verdict change
// from this function.
//
// Works are returned in their original order minus the drops, because the
// caller's downstream code (relevance ordering, all_studies) depends on it.
func dedupeVersions(works []scWork) ([]scWork, dedupeReport) {
	// newest[family] = index into works of the best edition seen so far.
	newest := map[string]int{}
	// members[family] = every index belonging to that family, in fetch order.
	members := map[string][]int{}

	for i, w := range works {
		fam := doiFamily(w.DOI)
		if fam == "" {
			continue // no DOI: never deduplicable, see doiFamily.
		}
		members[fam] = append(members[fam], i)
		best, seen := newest[fam]
		if !seen || betterEdition(works[i], works[best]) {
			newest[fam] = i
		}
	}

	// drop[i] marks a superseded edition.
	drop := make([]bool, len(works))
	var families []string
	for fam, idxs := range members {
		if len(idxs) < 2 {
			continue
		}
		keep := newest[fam]
		var dropped []string
		for _, i := range idxs {
			if i != keep {
				drop[i] = true
				dropped = append(dropped, editionLabel(works[i]))
			}
		}
		sort.Strings(dropped)
		families = append(families, fmt.Sprintf(
			"%s: kept %s, dropped %s",
			fam, editionLabel(works[keep]), strings.Join(dropped, ", ")))
	}
	// Stable output: map iteration order is randomized in Go, and a note whose
	// text changes between identical runs is not a measurement.
	sort.Strings(families)

	out := make([]scWork, 0, len(works))
	excluded := 0
	for i, w := range works {
		if drop[i] {
			excluded++
			continue
		}
		out = append(out, w)
	}

	return out, dedupeReport{Excluded: excluded, Families: families}
}

// betterEdition reports whether a supersedes b within one family.
//
// Publication year decides. The .pubN number is deliberately NOT the primary
// key: it is a Cochrane convention, and this function also has to rank the
// suffix-less original against its own revisions, where there is no N to read.
// Year is the property every edition actually carries.
//
// Ties (same year, which happens when OpenAlex records an edition's year as its
// reissue year) fall through to the higher .pubN, then to the longer DOI, so
// the choice is deterministic rather than dependent on fetch order.
func betterEdition(a, b scWork) bool {
	if a.Year != b.Year {
		return a.Year > b.Year
	}
	an, bn := editionNumber(a.DOI), editionNumber(b.DOI)
	if an != bn {
		return an > bn
	}
	return len(a.DOI) > len(b.DOI)
}

// editionNumber extracts N from a ".pubN" DOI suffix. A suffix-less DOI is
// edition 1, which is what Cochrane's original printing is.
func editionNumber(doi string) int {
	m := versionSuffixRE.FindString(strings.ToLower(doi))
	if m == "" {
		return 1
	}
	n := 0
	if _, err := fmt.Sscanf(m, ".pub%d", &n); err != nil {
		return 1
	}
	return n
}

// editionLabel renders one edition compactly for the note: year plus the DOI's
// edition tail, e.g. "2004 (.pub2)".
func editionLabel(w scWork) string {
	tail := versionSuffixRE.FindString(strings.ToLower(w.DOI))
	if tail == "" {
		tail = " (original)"
	} else {
		tail = " (" + tail + ")"
	}
	if w.Year > 0 {
		return fmt.Sprintf("%d%s", w.Year, tail)
	}
	return strings.TrimSpace(tail)
}
